defmodule Ryker.Operator.WorkspaceInputs do
  @moduledoc "Encrypted operator source archives bound to one admitted job and its first worker session."
  alias Ryker.{CoopFleet, Credentials, Repo, Secret, Work}
  alias Ryker.Operator.FleetJob

  defstruct [:id, :reference, :identity, :verification_digest]
  @maximum_bytes 10 * 1_024 * 1_024 * 1_024

  # The cleanup path joins the configured body root to a UUID generated by this admission.
  # sobelow_skip ["Traversal.FileModule"]
  def submit(id, placement, reference, chunks, options, submit_job) do
    with {:ok, job_id} <- Ecto.UUID.cast(id),
         true <-
           CoopFleet.Protocol.body_reference?(reference) and
             reference["byte_size"] <= @maximum_bytes,
         %{repository: repo, commit: base} when is_binary(repo) and is_binary(base) <- placement,
         root = root(options),
         true <- CoopFleet.Bodies.room?(root, reference["byte_size"]) do
      upload = %__MODULE__{id: Ecto.UUID.generate(), reference: reference}

      identity = %{
        "job_ref" => "operator-fleet-job:" <> job_id,
        "repository_ref" => repo,
        "base_revision" => base
      }

      key = Keyword.fetch!(options, :checkpoint_key)

      try do
        with :ok <- CoopFleet.Bodies.put(root, upload.id, :request, reference, chunks, key),
             {:ok, body, ^reference} <-
               CoopFleet.Bodies.fetch(root, upload.id, :request, reference),
             {:ok, manifest} <-
               CoopFleet.Bodies.with_stream(body, key, &validate(&1.(), reference, identity)) do
          upload = %{
            upload
            | verification_digest: verification_digest(manifest, placement[:purpose])
          }

          submit_job.(job_id, Map.put(placement, :workspace_input, upload))
        end
      after
        # An idempotent replay uses the original row. A failed admission has no
        # row. A process death here leaves an orphan for the retention worker.
        unless Repo.exists?(FleetJob.Query.by_input(upload.id)),
          do: File.rm_rf(Path.join(root, upload.id))
      end
    else
      _invalid -> {:error, :invalid_fleet_workspace}
    end
  end

  # Coop restores the submitted tracked tree as both index and working tree.
  # All fields in this encoding are ASCII; paths use canonical Base64.
  defp verification_digest(manifest, "verification") do
    files =
      manifest["untracked_files"]
      |> Enum.sort_by(& &1["path_bytes"])
      |> Enum.map(fn file ->
        [file["path_b64"], " ", Integer.to_string(file["mode"]), " ", file["sha256"], "\n"]
      end)

    tree = manifest["tracked_tree"]
    bytes = [manifest["committed_revision"], "\n", tree, "\n", tree, "\n", files]
    Base.encode16(:crypto.hash(:sha256, bytes), case: :lower)
  end

  defp verification_digest(_manifest, _purpose), do: nil

  defp validate(chunks, reference, identity) do
    secrets = Credentials.redaction_values() |> Enum.filter(&(byte_size(&1) >= 8)) |> Secret.new()

    CoopFleet.WorkspaceCheckpointBundle.validate_archive(
      reference,
      chunks,
      secrets,
      &CoopFleet.WorkspaceCheckpoint.decode_input_manifest(&1, identity)
    )
  end

  def with_download(options, input, consume) do
    with {:ok, body, _} <-
           CoopFleet.Bodies.fetch(root(options), input.id, :request, input.reference) do
      CoopFleet.Bodies.with_stream(
        body,
        Keyword.fetch!(options, :checkpoint_key),
        &consume_checked(&1, input, consume)
      )
    end
  end

  defp consume_checked(stream, input, consume) do
    with {:ok, _manifest} <- validate(stream.(), input.reference, input.identity),
         do: consume.(stream.())
  end

  def root(options), do: Path.join(Keyword.fetch!(options, :body_root), "operator-inputs")

  def authorize(certificate, job_ref) do
    with true <- CoopFleet.Protocol.reference?(job_ref),
         {:ok, worker} <- CoopFleet.ControlPlane.authenticate_certificate(certificate),
         [%{worker_job_document: job, worker_job_digest: digest} = session] <-
           Repo.all(Work.Session.Query.placed_job(job_ref, worker, Repo.now!())),
         %{
           "job_ref" => ^job_ref,
           "workspace_input" => ref,
           "source" => %{"repository_ref" => repository}
         } <- job,
         {:ok, ^digest} <- CoopFleet.JobSpec.digest(job),
         true <- CoopFleet.Client.initial_workspace?(session),
         %{"kind" => "commit", "sha" => base} <- session.repository_source,
         ^base <- get_in(job, ["source", "binding", "selected_commit"]),
         %{"offer_ref" => "operator-fleet-job:" <> id} <- session.workspace_task,
         %FleetJob{
           id: ^id,
           repository_ref: ^repository,
           workspace_input: ^ref,
           workspace_input_id: storage
         }
         when is_binary(storage) <- Repo.peek(FleetJob.Query.active_input(session.episode_id)) do
      identity = %{
        "job_ref" => "operator-fleet-job:" <> id,
        "repository_ref" => repository,
        "base_revision" => base
      }

      {:ok, %__MODULE__{id: storage, reference: ref, identity: identity}}
    else
      _refused -> {:error, :workspace_input_not_authorized}
    end
  end

  def prune(nil), do: :ok

  def prune(body_root) do
    body_root
    |> Path.join("operator-inputs")
    |> CoopFleet.Bodies.prune_orphans(fn id, old? ->
      old? and not Repo.exists?(FleetJob.Query.retained_input(id))
    end)
  end
end
